/** A single prop on a JSX element serialized to a flat key/value pair. */
export type StratoPropEntry = {
    property: string;
    value: string | number | boolean;
};
/** A direct strato-component JSX child of another strato-component element. */
export type StratoSubComponent = {
    component: string;
    properties: StratoPropEntry[];
    wrapperPackage?: string;
};
/** One strato-component JSX instance found in the app source. */
export type StratoInstance = {
    component: string;
    packageName: string;
    properties: StratoPropEntry[];
    subComponents: StratoSubComponent[];
    wrapperPackage?: string;
};
